"""Teacher-style working and direct original exam prompts; no copied exam items."""
def apply(qs):
 by={q['id']:q for q in qs}
 def w(key,*steps):
  by[key]['working']=[{'heading':step[0],'lines':list(step[1:])} for step in steps]
 def ask(key,text,parts=None):
  q=by[key];q['question']=text
  if parts:
   q['question']+='\n\n'+'\n\n'.join(f'({chr(97+i)}) {t} ({m} '+('mark' if m==1 else 'marks')+')' for i,(t,m) in enumerate(parts))
   q['partMarks']=[m for t,m in parts]
   assert sum(q['partMarks'])==q['marks'],key
 def replace(key,**kw):by[key].update(kw)
 # One mathematical operation per displayed line, retaining units and final conclusions.
 for i,(a,b,x,y) in enumerate([(2.5,8,6,25),(3,4,8,30),(1.2,15,10,24)]):
  pred=b+a*x
  w(f'maths_general-regression-v{i}',('Predicted value',f'ŷ = {b} + {a}x',f'ŷ = {b} + {a} × {x}',f'ŷ = {pred:g}'),('Residual','Residual = observed − predicted',f'Residual = {y} − {pred:g}',f'Residual = {y-pred:g}'))
 for i,(a,r,n) in enumerate([(200,1.05,4),(500,.9,3),(120,1.1,5)]):
  w(f'maths_general-sequence-v{i}',('Formula','uₙ = arⁿ⁻¹'),('Substitute',f'u{n} = {a} × {r}^({n} − 1)',f'u{n} = {a} × {r}^{n-1}'),('Calculate',f'u{n} = {a*r**(n-1):.2f} (to 2 decimal places)'))
 w('maths_general-seasonal',('Formula','Seasonally adjusted value = observed value ÷ seasonal index'),('Substitute and calculate','= 240 ÷ 1.20','= 200 units'),('Interpret','The quarter is typically 20% above the underlying level because of seasonality.'))
 w('maths_general-timezones',('Time difference','UTC offsets: +10 and −5','Difference = 10 − (−5) = 15 hours','City B is 15 hours behind City A.'),('Apply the difference','08:00 Monday − 15 hours','= 17:00 Sunday in City B'))
 w('maths_general-association',('Identify the evidence','The survey establishes an association between tutoring hours and scores.'),('Explain the limitation','An observational survey does not isolate tutoring from other influences.'),('Give a confounder','Prior achievement or motivation could affect both tutoring participation and exam scores.','The association alone does not establish causation.'))
 w('maths_general-networks',('Earliest finishes','A finishes at day 3.','B finishes at day 5.','C finishes at day 3 + 4 = 7.'),('Final activity','D can start only after both B and C.','D starts at max(5, 7) = day 7.','D finishes at day 7 + 2 = day 9.'),('Critical path and float','Critical path: A → C → D','Duration = 3 + 4 + 2 = 9 days','B can finish by day 7 without delaying D.','Float of B = 7 − 5 = 2 days'))
 w('maths_general-interest',('Formula','A = P(1 + r)ⁿ'),('Substitute','A = 5000(1 + 0.04)³','A = 5000 × 1.04³'),('Final balance','A = $5,624.32'))
 for i,a in enumerate([2,3,5]):
  w(f'maths_methods-exponential-v{i}',('Differentiate the exponential','For e^(u), the derivative is u′e^(u).',f'u = {a}x, so u′ = {a}.',f'd/dx[e^({a}x)] = {a}e^({a}x)'),('Differentiate the logarithm','d/dx[ln(x)] = 1/x'),('Combine',f'f′(x) = {a}e^({a}x) + 1/x, for x > 0'))
 w('maths_methods-trig',('Choose the rule','u = x², v = sin(x)','u′ = 2x, v′ = cos(x)','f′(x) = u′v + uv′'),('Substitute','f′(x) = (2x)sin(x) + x²cos(x)'),('Final derivative','f′(x) = 2x sin(x) + x² cos(x)'))
 w('maths_methods-stationary',('Differentiate','f′(x) = 2x − 6'),('Find the stationary value','2x − 6 = 0','x = 3'),('Find the coordinate','f(3) = 3² − 6(3) + 5','f(3) = −4'),('Classify','f″(x) = 2 > 0','The stationary point (3, −4) is a local minimum.'))
