 w('maths_methods-discrete',('Expected value','E(X) = ΣxP(X = x)','E(X) = 0(0.2) + 1(0.5) + 2(0.3)','E(X) = 1.1'),('Required probability','P(X ≥ 1) = P(X = 1) + P(X = 2)','= 0.5 + 0.3','= 0.8'))
 w('maths_methods-normal',('Standardise','z = (x − μ)/σ','z = (62 − 50)/8','z = 1.5'),('Use the upper tail','P(X > 62) = P(Z > 1.5)','= 1 − Φ(1.5)','= 1 − 0.9332','= 0.0668'))
 w('maths_methods-ci',('Sample proportion','p̂ = 240/400 = 0.60'),('Standard error','SE = √[p̂(1 − p̂)/n]','SE = √[(0.60)(0.40)/400]','SE ≈ 0.024495'),('Margin of error','ME = 1.96 × SE','ME ≈ 0.04801'),('Confidence interval','p̂ ± ME = 0.60 ± 0.04801','Approximate 95% interval: [0.5520, 0.6480]','Equivalent to approximately 55.20% to 64.80%.'))
 w('maths_specialist-complex',('Polar form','1 + i = √2[cos(π/4) + i sin(π/4)]'),('Apply De Moivre’s theorem','(1 + i)⁴ = (√2)⁴[cos(4π/4) + i sin(4π/4)]','= 4[cos(π) + i sin(π)]'),('Cartesian form','= 4(−1 + 0i)','= −4'))
 w('maths_specialist-induction',('Base case: n = 1','Left side = 1','Right side = 1(1 + 1)/2 = 1','The statement is true for n = 1.'),('Induction hypothesis','Assume 1 + 2 + … + k = k(k + 1)/2 for a positive integer k.'),('Inductive step','1 + 2 + … + k + (k + 1)','= k(k + 1)/2 + (k + 1)','= (k + 1)(k + 2)/2','This is the required formula for n = k + 1.'),('Conclusion','The statement holds for every positive integer n by mathematical induction.'))
 w('maths_specialist-vectors',('Dot products','a · b = 2(1) + 1(0) + 2(1) = 4','b · b = 1² + 0² + 1² = 2'),('Projection formula','proj_b(a) = [(a · b)/(b · b)]b'),('Substitute and simplify','= (4/2)(1, 0, 1)','= (2, 0, 2)'))
