 w('chemistry-equilibrium',('Equilibrium expression','Kc = [HI]² / ([H₂][I₂])'),('Substitute','Kc = 0.80² / (0.20 × 0.20)','Kc = 0.64/0.04','Kc = 16'),('Compare Qc with Kc','Qc = 4 < Kc = 16','The net reaction proceeds towards products until equilibrium is reached.'))
